function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.businessLogic || {};

  // 計算結果を格納する配列
  let calculationResults = [];

  // 店舗データを取得してセレクトボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのテーブルインデックス
      const storeSelect = container.querySelector('#select-store');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗データの取得に失敗しました');
    }
  }

  // 商品データを取得してセレクトボックスに設定
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタのテーブルインデックス
      const productSelect = container.querySelector('#select-product');
      productSelect.innerHTML = '<option value="">商品を選択してください</option>';

      if (products) {
        products.forEach(product => {
          const option = document.createElement('option');
          option.value = product.id;
          option.textContent = `${product.商品名} (${product.商品コード})`;
          productSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error('商品データの取得に失敗しました');
    }
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    try {
      const storeId = container.querySelector('#select-store').value;
      const productId = container.querySelector('#select-product').value;
      const startDate = container.querySelector('#start-date').value;
      const endDate = container.querySelector('#end-date').value;

      if (!storeId || !productId || !startDate || !endDate) {
        window.aivicNotify.error('すべての項目を入力してください');
        return;
      }

      // 売上データ収集
      const salesData = await collectSalesData(storeId, productId, startDate, endDate);
      if (!salesData || salesData.length === 0) {
        window.aivicNotify.error('売上データが見つかりません');
        return;
      }

      // 商品別・店舗別データ分類
      const productClassifiedData = classifySalesDataByProduct(salesData);
      const storeClassifiedData = classifySalesDataByStore(salesData);

      // 有効な商品データのフィルタリング
      const validProductData = filterValidProductData(productClassifiedData);

      // 外部要因データ収集
      const weatherData = await collectWeatherData(storeId, startDate, endDate);
      const eventData = await collectEventData(storeId, startDate, endDate);
      const seasonalData = await collectSeasonalData(startDate, endDate);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 履歴データとの比較
      const historicalComparison = await compareWithHistoricalData(salesData, storeId, productId);

      // 比較期間の妥当性検証
      const periodValidation = validateComparisonPeriod(startDate, endDate);
      if (!periodValidation.isValid) {
        window.aivicNotify.error(periodValidation.message);
        return;
      }

      // 計算結果の生成
      const calculationResult = {
        id: Date.now(),
        商品名: validProductData[0]?.商品名 || '',
        商品コード: validProductData[0]?.商品コード || '',
        現在在庫: validProductData[0]?.現在在庫 || 0,
        予測需要量: Math.round(salesData.reduce((sum, item) => sum + (item.売上数量 || 0), 0) / salesData.length * 30),
        安全在庫: Math.round(validProductData[0]?.現在在庫 * 0.2) || 0,
        発注点: 0,
        推奨発注量: 0,
        計算日時: new Date().toLocaleString('ja-JP'),
        weatherCorrelation,
        eventCorrelation,
        seasonalCorrelation,
        historicalComparison
      };

      calculationResult.発注点 = calculationResult.予測需要量 + calculationResult.安全在庫;
      calculationResult.推奨発注量 = Math.max(0, calculationResult.発注点 - calculationResult.現在在庫);

      calculationResults.unshift(calculationResult);
      renderCalculationResults(calculationResults);

      window.aivicNotify.success('発注量計算が完了しました');

    } catch (error) {
      console.error('計算エラー:', error);
      window.aivicNotify.error('計算処理中にエラーが発生しました');
    }
  }

  // 計算結果テーブルの再描画
  function renderCalculationResults(results) {
    const tbody = container.querySelector('#calculation-results');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>${result.安全在庫 || 0}</td>
        <td>${result.発注点 || 0}</td>
        <td>${result.推奨発注量 || 0}</td>
        <td>${result.計算日時 || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id}">詳細</button>
        </td>
      </tr>
    `).join('');

    // 詳細ボタンのイベントリスナーを追加
    const detailButtons = tbody.querySelectorAll('.detail-btn');
    detailButtons.forEach(button => {
      button.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        showCalculationDetail(id);
      });
    });
  }

  // 計算詳細表示
  function showCalculationDetail(id) {
    const result = calculationResults.find(r => r.id == id);
    if (!result) {
      window.aivicNotify.error('計算結果が見つかりません');
      return;
    }

    const detailHtml = `
      <div class="calculation-detail">
        <h3>計算詳細 - ${result.商品名}</h3>
        <div class="detail-grid">
          <div class="detail-item">
            <label>天候相関:</label>
            <span>${result.weatherCorrelation?.correlation || 'N/A'}</span>
          </div>
          <div class="detail-item">
            <label>イベント相関:</label>
            <span>${result.eventCorrelation?.correlation || 'N/A'}</span>
          </div>
          <div class="detail-item">
            <label>季節相関:</label>
            <span>${result.seasonalCorrelation?.correlation || 'N/A'}</span>
          </div>
          <div class="detail-item">
            <label>履歴比較:</label>
            <span>${result.historicalComparison?.variance || 'N/A'}</span>
          </div>
        </div>
        <button class="action-btn secondary close-detail-btn">閉じる</button>
      </div>
    `;

    const detailContainer = container.querySelector('#calculation-detail');
    if (detailContainer) {
      detailContainer.innerHTML = detailHtml;
      detailContainer.style.display = 'block';

      const closeBtn = detailContainer.querySelector('.close-detail-btn');
      closeBtn.addEventListener('click', () => {
        detailContainer.style.display = 'none';
      });
    }
  }

  // 結果クリア
  function clearResults() {
    calculationResults = [];
    renderCalculationResults(calculationResults);
    window.aivicNotify.success('計算結果をクリアしました');
  }

  // エラーメッセージ表示
  function showError(message) {
    window.aivicNotify.error(message);
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    const calculateBtn = container.querySelector('#calculate-btn');
    const clearBtn = container.querySelector('#clear-results-btn');

    if (calculateBtn) {
      calculateBtn.addEventListener('click', calculateOrderQuantity);
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', clearResults);
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadProducts();
      setupEventListeners();
      renderCalculationResults(calculationResults);
    } catch (error) {
      console.error('初期化エラー:', error);
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
